package br.com.social.comment;import jakarta.persistence.*;import java.time.LocalDateTime;@Entity @Table(name="comments")public class Comment{@Id @GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@Column(nullable=false)private Long postId;private String authorEmail;private String authorName;@Column(nullable=false,length=800)private String content;@Column(nullable=false)private LocalDateTime createdAt;public Comment(){}public Comment(Long p,String e,String n,String c){postId=p;authorEmail=e;authorName=n;content=c;createdAt=LocalDateTime.now();}public Long getId(){return id;}public Long getPostId(){return postId;}public String getAuthorEmail(){return authorEmail;}public String getAuthorName(){return authorName;}public String getContent(){return content;}public LocalDateTime getCreatedAt(){return createdAt;}}